/bin/bash -lc "python3 - <<'PY'
import ast,json,pathlib,subprocess,hashlib,importlib.util
proposal=json.loads(pathlib.Path('proposal.json').read_text())
runtime=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','run://r-001'],text=True))
schema=runtime['study_schema']
def validate(value,schema,path='study'):
    types={'object':dict,'array':list,'string':str,'boolean':bool,'number':(int,float),'integer':int}
    if 'type' in schema:
        assert isinstance(value,types[schema['type']]),(path,'type')
    if isinstance(value,dict):
        assert all(k in value for k in schema.get('required',[])),(path,'required')
        props=schema.get('properties',{})
        if schema.get('additionalProperties') is False:
            assert not (set(value)-set(props)),(path,'additional keys')
        for k,v in value.items():
            if k in props: validate(v,props[k],path+'.'+k)
    if isinstance(value,list):
        assert len(value)>=schema.get('minItems',0),(path,'minItems')
        for i,v in enumerate(value): validate(v,schema.get('items',{}),path+'.'+str(i))
    if isinstance(value,str): assert len(value)>=schema.get('minLength',0),(path,'length')
    if 'enum' in schema: assert value in schema['enum'],(path,'enum')
    if 'const' in schema: assert value==schema['const'],(path,'const')
validate(proposal['study'],schema)
assert proposal['study']['protocol_ref']==runtime['required_study_protocol_ref']
assert proposal['parent_trial'] in runtime['context']['allowed_observation_ids']
assert set(proposal['study']['evidence_refs']) <= set(runtime['context']['allowed_observation_ids'])
assert len({v['name'] for v in proposal['variants']})==4
assert len({v['file'] for v in proposal['variants']})==4
assert any(v['role']=='candidate' for v in proposal['variants'])
ancestor=ast.parse(pathlib.Path('history_g2_r0017_sketch256.py').read_text())
def methods(tree): return {n.name:n for n in next(n for n in tree.body if isinstance(n,ast.ClassDef)).body if isinstance(n,ast.FunctionDef)}
old=methods(ancestor)
unchanged={'_age_ids','_fine_counts','_factorized_recency','_recency_weights','_context_from_counts','_features','forward','_match_counts','_statistics','_membership','_histogram','_identity_features','_dense_distribution','_bucket_ids','_bucket_table'}
allowed_imports={'math','torch'}
cells=set()
for v in proposal['variants']:
    file=pathlib.Path(v['file'])
    assert file.name==v['file'] and file.suffix=='.py'
    source=file.read_text()
    tree=ast.parse(source)
    compile(source,str(file),'exec')
    c=ast.literal_eval(next(n.value for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets)))
    assert c==v['config']
    cells.add((c['use_entropy'],c['use_collision']))
    for node in ast.walk(tree):
        if isinstance(node,ast.Import): assert all(i.name.split('.')[0] in allowed_imports for i in node.names)
        if isinstance(node,ast.ImportFrom): assert node.module.split('.')[0] in allowed_imports
        if isinstance(node,ast.Call) and isinstance(node.func,ast.Name): assert node.func.id not in {'open','eval','exec','__import__'}
    new=methods(tree)
    for name in unchanged: assert ast.dump(new[name])==ast.dump(old[name]),(v['name'],name)
    # Check all parameter allocations/initialization expressions stay identical.
    def learned_calls(init):
        return [ast.dump(n) for n in ast.walk(init) if isinstance(n,ast.Call) and isinstance(n.func,ast.Attribute) and (isinstance(n.func.value,ast.Name) and n.func.value.id=='nn' or isinstance(n.func.value,ast.Attribute) and isinstance(n.func.value.value,ast.Name) and n.func.value.value.id=='nn')]
    assert learned_calls(new['__init__'])==learned_calls(old['__init__'])
    diag=next(n.value for n in ast.walk(new['diagnostics']) if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='result' for t in n.targets))
    assert isinstance(diag,ast.Dict) and len(diag.keys)<=64
    assert 'Source SHA256='+hashlib.sha256(file.read_bytes()).hexdigest() in v['note']
    print(v['name']+': compiled; CONFIG matches; inherited feature methods and learned allocation unchanged; '+str(len(diag.keys))+' diagnostics')
assert cells=={(True,True),(True,False),(False,True),(False,False)}
print('Study schema, evidence IDs, protocol identity, factorial coverage, imports and source hashes passed.')
print('Torch numeric checks and training were not run; host execution required.')
PY"

